const cooldown=[0,0,0,0],abilityNames=['REPULSOR','UNIBEAM','MISSILES','FLIGHT BOOST'],abilityIcons=['✦','ϟ','➤','»'];
let camYaw=0,camPitch=-.08,camPos=[0,0,0],camTarget=[0,0,0],aimDir=[0,0,1],targetEnemy=null;
function updateCamera(dt){const f=[Math.sin(camYaw),0,Math.cos(camYaw)];const desired=[player.x-f[0]*7,player.y+3.1,player.z-f[2]*7];camPos[0]=lerp(camPos[0],desired[0],1-Math.exp(-dt*9));camPos[1]=lerp(camPos[1],desired[1],1-Math.exp(-dt*9));camPos[2]=lerp(camPos[2],desired[2],1-Math.exp(-dt*9));camTarget=[player.x+f[0]*2,player.y+1.6,player.z+f[2]*2];aimDir=norm([Math.sin(camYaw)*Math.cos(camPitch),Math.sin(camPitch),Math.cos(camYaw)*Math.cos(camPitch)])}
function project(p){const f=norm(sub(camTarget,camPos)),r=norm([f[2],0,-f[0]]),u=[r[1]*f[2]-r[2]*f[1],r[2]*f[0]-r[0]*f[2],r[0]*f[1]-r[1]*f[0]],v=sub(p,camPos),z=dot(v,f);if(z<=.1)return null;const focal=canvas.height*.95;return {x:canvas.width/2+dot(v,r)*focal/z,y:canvas.height/2-dot(v,u)*focal/z,z}}
function setTarget(){targetEnemy=null;let best=1e9;const rad=(settings.radius||.22)*Math.min(innerWidth,innerHeight);for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(e.x-player.x,e.z-player.z);if(d>settings.maxDist)continue;const p=project([e.x,e.y+1.15,e.z]);if(!p)continue;const sx=(p.x/canvas.width-.5)*innerWidth,sy=(p.y/canvas.height-.5)*innerHeight,dist=Math.hypot(sx,sy);if(dist<rad&&dist<best){const toward=norm([e.x-player.x,1.15-player.y,e.z-player.z]);if(dot(toward,aimDir)<.45)continue;best=dist;targetEnemy=e}}}
function pushPart(x,y,z,w,h,d,color,yaw=0){drawCube(x,y,z,w,h,d,color,yaw)}
function drawHero(x,y,z,yaw,anim,isEnemy=false){const bob=Math.sin(anim*8)*.04,red=isEnemy?0x644d42:0xc93339,gold=isEnemy?0x91663f:0xe9ad43,blue=isEnemy?0x5c5350:0x55e6f4;const s=isEnemy?.72:1.0;pushPart(x,y+bob,z,.72*s,.76*s,.42*s,red,yaw);pushPart(x,y+.78*s+bob,z,.52*s,.54*s,.48*s,gold,yaw);pushPart(x,y+1.22*s+bob,z,.45*s,.42*s,.42*s,red,yaw);if(!isEnemy){pushPart(x,y+.56*s+bob,z+.22*s,.25*s,.25*s,.08,blue,yaw);pushPart(x-.27*s,y+1.28*s+bob,z+.21*s,.13*s,.07,.07,blue,yaw);pushPart(x+.27*s,y+1.28*s+bob,z+.21*s,.13*s,.07,.07,blue,yaw)}
const swing=Math.sin(anim*9)*.22,leg=Math.sin(anim*9)*.2;pushPart(x-.24*s,y-.48*s+bob,z+leg,.22*s,.55*s,.24*s,gold,yaw);pushPart(x+.24*s,y-.48*s+bob,z-leg,.22*s,.55*s,.24*s,gold,yaw);pushPart(x-.5*s,y+.16*s+bob,z+swing*.5,.23*s,.58*s,.25*s,red,yaw);pushPart(x+.5*s,y+.16*s+bob,z-swing*.5,.23*s,.58*s,.25*s,red,yaw);}
function updateRenderer(){resize();if(!gpu)return;const dev=gpu.device;const proj=perspective(mat4(),1.02,canvas.width/canvas.height,.1,280),view=lookAt(mat4(),camPos,camTarget),vp=mul(mat4(),proj,view);dev.queue.writeBuffer(gpu.uniform,0,vp);verts.length=0;verts.push(...city); // static city first; dynamic geometry appended below
const t=time;for(const e of enemies){if(e.alive)drawHero(e.x,e.y,e.z,Math.atan2(e.vx,e.vz)||e.seed,e.seed+t,true)}drawHero(player.x,player.y,player.z,player.yaw,player.anim,false);
for(const p of projectiles)if(p.active){const color=p.kind==='missile'?0xff8a36:0x55efff;cube(p.x,p.y,p.z,p.kind==='missile'?.28:.18,p.kind==='missile'?.28:.18,p.kind==='missile'?.48:.18,color,Math.atan2(p.vx,p.vz));cube(p.x,p.y,p.z,.34,.34,.34,0xfff1a4)}
for(const p of particles)if(p.active)cube(p.x,p.y,p.z,p.size,p.size,p.size,p.color);
const data=new Float32Array(verts);if(!gpu.vertex||gpu.capacity<data.byteLength){gpu.capacity=Math.max(data.byteLength*1.5,1024*1024);gpu.vertex=dev.createBuffer({size:Math.ceil(gpu.capacity/4)*4,usage:GPUBufferUsage.VERTEX|GPUBufferUsage.COPY_DST})}dev.queue.writeBuffer(gpu.vertex,0,data);const encoder=dev.createCommandEncoder();const pass=encoder.beginRenderPass({colorAttachments:[{view:gpu.context.getCurrentTexture().createView(),clearValue:{r:.39,g:.68,b:.86,a:1},loadOp:'clear',storeOp:'store'}],depthStencilAttachment:{view:gpu.depth.createView(),depthClearValue:1,depthLoadOp:'clear',depthStoreOp:'store'}});pass.setPipeline(gpu.pipeline);pass.setBindGroup(0,gpu.bind);pass.setVertexBuffer(0,gpu.vertex);pass.draw(data.length/6);pass.end();dev.queue.submit([encoder.finish()]);}

