makeSettings();resize();updateCamera(1);let renderedFallback=false;
async function boot(){await initRenderer();requestAnimationFrame(frame)}
function frame(now){const dt=Math.min(.05,(now-last)/1000||.016);last=now;update(dt);if(gpu)updateRenderer();else{drawFallback();renderedFallback=true}requestAnimationFrame(frame)}
boot();

