const WebSocket=require('ws');
const http=require('http');
function get(p){return new Promise((ok,no)=>http.get(p,r=>{let d='';r.on('data',x=>d+=x);r.on('end',()=>ok(JSON.parse(d)))}).on('error',no))}
async function main(){
 const pages=await get('http://127.0.0.1:9222/json'); const page=pages.find(p=>p.type==='page');
 const ws=new WebSocket(page.webSocketDebuggerUrl); let id=0; const pending=new Map();
 ws.on('message',b=>{const m=JSON.parse(b);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}}); await new Promise(r=>ws.on('open',r));
 const send=(method,params={})=>new Promise(r=>{const n=++id;pending.set(n,r);ws.send(JSON.stringify({id:n,method,params}))});
 await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
 await send('Runtime.evaluate',{expression:"$('#play').click()"}); await new Promise(r=>setTimeout(r,300));
 await send('Runtime.evaluate',{expression:"$('#launch').click()"}); await new Promise(r=>setTimeout(r,1800));
 await send('Runtime.evaluate',{expression:"keys.KeyW=true; keys.Space=true"}); await new Promise(r=>setTimeout(r,2500));
 await send('Runtime.evaluate',{expression:"keys.KeyW=false; keys.Space=false; ability(1); ability(2); ability(3);"}); await new Promise(r=>setTimeout(r,1200));
 await send('Runtime.evaluate',{expression:"JSON.stringify({state:gameState,hud:ui.hud.style.display,player:{x:player.x,y:player.y,z:player.z,hp:player.hp,fly:player.fly},enemies:enemies.filter(e=>e.alive).length,coins,canvas:[canvas.width,canvas.height],gpu:!!gpu,fallback:!!ctx})"}).then(r=>console.log(JSON.stringify(r.result.result.value)));
 await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});
 ws.close();
}
main();
EOF
